package imagesearch

import (
	"errors"

	"github.com/anthnel/devdesk/internal/oci"
)

// Verdict is one registry's answer to a search. The zero value is not a
// verdict: it means no answer yet, and Classify never returns it.
type Verdict int

const (
	// VerdictOK means rows were found.
	VerdictOK Verdict = iota + 1
	// VerdictNoResult means the registry answered and nothing matches.
	VerdictNoResult
	// VerdictRefused means unsupported or refused.
	VerdictRefused
	// VerdictFailed means network, deadline, 5xx, 429, unreadable body or a proxy whose
	// upstream is temporarily blocked (a 404 that says so).
	VerdictFailed
)

// String is the verdict as shown to the user.
func (v Verdict) String() string {
	switch v {
	case VerdictOK:
		return "ok"
	case VerdictNoResult:
		return "no result"
	case VerdictRefused:
		return "unsupported or refused"
	case VerdictFailed:
		return "failed"
	}
	return "pending"
}

// Outcome is a verdict and its marks. Invariant: Partial is set only with ok
// or no result (a partial walk that found nothing is still "no result"), never
// with refused or failed.
type Outcome struct {
	Verdict Verdict
	Partial bool
	Skipped bool
}

// ErrQueryTooShort: the catalog was not walked, the query is too short.
var ErrQueryTooShort = errors.New("query too short to walk a catalog")

// ErrPrefixNotInCatalog: no catalog name carries the entry's prefix.
var ErrPrefixNotInCatalog = errors.New("no catalog name carries the entry's prefix")

// Classify turns a search answer (error, row count, partial flag) into one
// Outcome. An error always wins over n and partial. With no error, n == 0
// keeps the Partial mark: the verdict is "no result" and Partial is set when
// the walk was cut short.
func Classify(err error, n int, partial bool) Outcome {
	switch {
	case err == nil && n == 0:
		return Outcome{Verdict: VerdictNoResult, Partial: partial}
	case err == nil:
		return Outcome{Verdict: VerdictOK, Partial: partial}
	case errors.Is(err, ErrQueryTooShort):
		return Outcome{Verdict: VerdictNoResult, Skipped: true}
	case errors.Is(err, ErrUnsupported), errors.Is(err, ErrPrefixNotInCatalog):
		return Outcome{Verdict: VerdictRefused}
	}
	var se *oci.StatusError
	if errors.As(err, &se) && !se.UpstreamBlocked() && refusedStatus(se) {
		return Outcome{Verdict: VerdictRefused}
	}
	return Outcome{Verdict: VerdictFailed}
}

// refusedStatus tells a refusal from a failure: the registry refusing the
// request (401, 403, 404, 405) or the token endpoint refusing the credentials
// (401, 403). Any other status, 429 and 5xx included, is a failure.
func refusedStatus(se *oci.StatusError) bool {
	switch se.Code {
	case 401, 403:
		return true
	case 404, 405:
		return se.Source != oci.SourceToken
	}
	return false
}
}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
	if b.outcomes == nil {
		b.outcomes = map[string]imagesearch.Outcome{}
	}
	b.outcomes[msg.EntryKey] = oc
	if oc.Verdict == imagesearch.VerdictOK {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
// back to the form; esc acts in order: the filter bar while it is open, then a
// confirmed query, then it cancels the lot and goes back to the form (which
// keeps the typed name and the selection). The lot's late answers are no
// longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet; → opens the row's tags.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case ".":
		b.cycleSearchSort()
		return b, nil
	case "r":
		b.cycleSearchRegistryFilter()
		return b, nil
	case "right":
		return b.openSelectedImageTags()
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			// The cursor stays on the selected row once the filter is gone.
			prev, had := b.searchTable.Selected()
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			b.reselect(prev, had)
			return b, nil
		}
		return b.backToForm()
	case "left":
		return b.backToForm()
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// backToForm cancels the lot and returns to the form, which keeps the typed
// name and the selection. Late answers of the lot are dropped.
func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
	b.abandonLot()
	b.state = browserStateInput
	b.searchTable.Blur()
	b.updateFocus()
	return b, nil
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
	alias := msg.EntryKey
	if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
		alias = entryAlias(*e)
	}
	logSearchOutcome(alias, oc, msg.Err)
	if reason := registryFailureReason(msg.Err); reason != "" {
		return m, m.footer.Error("Image search on " + alias + ": " + reason)
	}
	return m, nil
}

// logSearchOutcome logs a registry's verdict: failed as an error, refused as
// info, nothing for ok or no result. The cause goes through searchErrorCause,
// so no secret or typed text reaches the log.
func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
	switch oc.Verdict {
	case imagesearch.VerdictFailed:
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
	case imagesearch.VerdictRefused:
		log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
	}
}

// searchErrorCause is the loggable text of a search error. A *url.Error holds
// the full request URL, which carries the text the user typed, so only its Op
// and Err are kept.
func searchErrorCause(err error) string {
	var ue *url.Error
	if errors.As(err, &ue) {
		return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
	}
	return jobs.SafeCause(err)
}

// handleRegistryBrowserWarn shows the browser's warning in the footer.
func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
	return m, m.footer.Warn(strings.TrimSpace(msg.Text))
}

