func TestHubSearchAppliesTheRegistryPrefixOnce(t *testing.T) {
	srv, _ := fakeHub(t)
	withImageSearcher(t, imagesearch.ByRegistry(imagesearch.HubSearcher{Endpoint: srv.URL, Client: srv.Client()}, nil))

