	}
	rows := m.registryBrowser.searchTable.Visible()
	if len(rows) != 1 || rows[0].img.Repo != "bitnami/nginx" {
		t.Fatalf("rows = %+v, want the single bitnami/nginx (prefix applied once)", rows)
	}
}
