var reqLogPath = os.Getenv("M_REQLOG")

const hardCap = 24

type countRT struct {
	mu   sync.Mutex
	base http.RoundTripper
}

func countLines() int {
	b, _ := os.ReadFile(reqLogPath)
	return strings.Count(string(b), "\n")
}

func (c *countRT) RoundTrip(r *http.Request) (*http.Response, error) {
	c.mu.Lock()
	n := countLines()
	if n >= hardCap {
		c.mu.Unlock()
		return nil, fmt.Errorf("MEASURE HARD CAP of %d requests reached", hardCap)
	}
	line := fmt.Sprintf("%s %s", r.Method, r.URL.String())
	f, _ := os.OpenFile(reqLogPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	t0 := time.Now()
	c.mu.Unlock()
	resp, err := c.base.RoundTrip(r)
	var extra string
	if err != nil {
		extra = " -> ERR " + err.Error()
	} else {
		extra = fmt.Sprintf(" -> %d", resp.StatusCode)
		for k, v := range resp.Header {
			lk := strings.ToLower(k)
			if strings.HasPrefix(lk, "ratelimit") || strings.HasPrefix(lk, "docker-ratelimit") || lk == "retry-after" || lk == "location" || lk == "www-authenticate" {
				extra += fmt.Sprintf(" [%s: %s]", lk, strings.Join(v, ","))
			}
		}
	}
	c.mu.Lock()
	fmt.Fprintf(f, "%s%s (%dms)\n", line, extra, time.Since(t0).Milliseconds())
	_ = f.Close()
	c.mu.Unlock()
	if err == nil && resp.StatusCode == 429 {
		_ = os.WriteFile(reqLogPath+".429", []byte("429 seen\n"), 0o600)
	}
	return resp, err
}

func installCounter(t *testing.T) {
	t.Helper()
	if os.Getenv("MEASURE_HUB") != "1" {
		t.Skip("measurement only")
	}
	if _, err := os.Stat(reqLogPath + ".429"); err == nil {
		t.Fatal("a 429 was seen earlier: stop")
	}
	prev := http.DefaultTransport
	http.DefaultTransport = &countRT{base: prev}
	t.Cleanup(func() { http.DefaultTransport = prev })
	log2 := os.Stderr
	_ = log2
}

