// runWanted runs every leaf Cmd concurrently and returns the messages of the wanted types.
func runWanted(cmd tea.Cmd, want int, wait time.Duration) []tea.Msg {
	var leaves []tea.Cmd
	var flatten func(c tea.Cmd)
	flatten = func(c tea.Cmd) {
		if c == nil {
			return
		}
		leaves = append(leaves, c)
	}
	flatten(cmd)
	out := make(chan tea.Msg, 16)
	var expand func(c tea.Cmd)
	expand = func(c tea.Cmd) {
		go func() {
			msg := c()
			if b, ok := msg.(tea.BatchMsg); ok {
				for _, cc := range b {
					expand(cc)
				}
				return
			}
			switch msg.(type) {
			case ImageSearchResultMsg, MultiRegistryTagsLoadedMsg, MultiRegistryTagsMetaMsg, RegistryBrowserWarnMsg:
				out <- msg
			}
		}()
	}
	for _, c := range leaves {
		expand(c)
	}
	var got []tea.Msg
	deadline := time.After(wait)
	for len(got) < want {
		select {
		case m := <-out:
			got = append(got, m)
		case <-deadline:
			return got
		}
	}
	return got
}

func show(t *testing.T, label string, m Model) {
	t.Helper()
	t.Logf("---- %s: VIEW ----\n%s", label, trimBlank(ansi.Strip(m.Render())))
	t.Logf("---- %s: FOOTER ----\n%s", label, ansi.Strip(m.RenderFooter(200)))
}

func trimBlank(s string) string {
	var out []string
	for _, l := range strings.Split(s, "\n") {
		if strings.TrimSpace(l) != "" {
			out = append(out, strings.TrimRight(l, " "))
		}
	}
	return strings.Join(out, "\n")
}

// feedAll feeds each message and then runs the follow-up Cmd for wanted types.
func feedAll(t *testing.T, m Model, msgs []tea.Msg, followWant int) (Model, []tea.Msg) {
	t.Helper()
	var follow []tea.Msg
	for _, msg := range msgs {
		var cmd tea.Cmd
		m, cmd = step(t, m, msg)
		if cmd != nil && followWant > 0 {
			follow = append(follow, runWanted(cmd, followWant, 25*time.Second)...)
		}
	}
	return m, follow
