		got := runWanted(cmd, 1, 30*time.Second)
		t.Logf("search answers: %d", len(got))
		for _, g := range got {
			if r, ok := g.(ImageSearchResultMsg); ok {
				t.Logf("ImageSearchResultMsg: images=%d partial=%v err=%v (%T)", len(r.Images), r.Partial, r.Err, r.Err)
				for i, im := range r.Images {
					if i < 8 {
						t.Logf("  row %d: name=%q repo=%q official=%v stars=%d/%v desc=%.50q", i, im.Name, im.Repo, im.Official, im.Stars, im.HasStars, im.Description)
					}
				}
			}
		}
		m, _ = feedAll(t, m, got, 0)
		t.Logf("outcomes: %+v", m.RegistryBrowserOutcomes())
		show(t, "after search", m)
		if mode == "searchtags" {
			for i := 0; i < 60; i++ {
				row, _, ok := m.registryBrowser.selectedImage()
				if ok && row.img.Repo == "library/nginx" {
					break
				}
				m = feed(t, m, testutil.Key("down"))
			}
			row, _, _ := m.registryBrowser.selectedImage()
			t.Logf("selected row: %+v", row.img)
			m2, cmd := step(t, m, testutil.Key("right"))
			m = m2
			got := runWanted(cmd, 1, 30*time.Second)
			var follow []tea.Msg
			m, follow = feedAll(t, m, got, 1)
			for _, g := range got {
				if r, ok := g.(MultiRegistryTagsLoadedMsg); ok {
					t.Logf("TagsLoaded: repo=%q tags=%d err=%v", r.Repo, len(r.Tags), r.Err)
				}
			}
			m, _ = feedAll(t, m, follow, 0)
			for _, g := range follow {
				if r, ok := g.(MultiRegistryTagsMetaMsg); ok {
					t.Logf("TagsMeta: repo=%q dates=%d err=%v", r.Repo, len(r.Meta), r.Err)
				}
			}
			t.Logf("tags in browser: %d", len(m.registryBrowser.tags))
			for i, tg := range m.registryBrowser.tags {
				if i < 6 {
					t.Logf("  tag %q updated=%v", tg.Tag, tg.UpdatedAt)
				}
			}
			show(t, "after tags", m)
		}
	case "tags":
		m2, cmd := submitRaw(t, m, "library/nginx")
		m = m2
		got := runWanted(cmd, 1, 30*time.Second)
		var follow []tea.Msg
		m, follow = feedAll(t, m, got, 1)
		for _, g := range got {
			if r, ok := g.(MultiRegistryTagsLoadedMsg); ok {
				t.Logf("TagsLoaded: repo=%q tags=%d err=%v (%T)", r.Repo, len(r.Tags), r.Err, r.Err)
			}
		}
		m, _ = feedAll(t, m, follow, 0)
		for _, g := range follow {
			if r, ok := g.(MultiRegistryTagsMetaMsg); ok {
				t.Logf("TagsMeta: repo=%q dates=%d err=%v", r.Repo, len(r.Meta), r.Err)
			}
		}
		show(t, "after direct tags", m)
	}
}

func TestMeasurePull(t *testing.T) {
	installCounter(t)
	ref := multiImageName("docker.io", "library/hello-world", "latest")
	t.Logf("reference handed to the engine pull: %q", ref)
	cfg := config.Default()
	deps := imagepull.Default(cfg, nil)
	t.Logf("verification enabled: %v", deps.Enabled)
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	_ = ctx
	cmd := pullOneImageCmd(ref, deps)
	for _, msg := range testutil.Msgs(cmd) {
		switch r := msg.(type) {
		case RegistryPullCompleteMsg:
			t.Logf("RegistryPullCompleteMsg: err=%v check=%+v", r.Err, r.Check)
		default:
			t.Logf("msg %T", msg)
		}
	}
}

func TestMeasureUnreachable(t *testing.T) {
	installCounter(t)
	_ = io.Discard
	url := "docker.io"
	m := hubModel(t, url)
	m2, cmd := submitRaw(t, m, "nginx")
	m = m2
	got := runWanted(cmd, 1, 40*time.Second)
	for _, g := range got {
		if r, ok := g.(ImageSearchResultMsg); ok {
			t.Logf("search: images=%d err=%v (%T)", len(r.Images), r.Err, r.Err)
		}
	}
	m, _ = feedAll(t, m, got, 0)
	t.Logf("outcomes: %+v", m.RegistryBrowserOutcomes())
	show(t, "unreachable search", m)

	// tags from the form
	m = feed(t, m, testutil.Key("esc"))
	m3, cmd := submitRaw(t, m, "library/nginx")
	m = m3
	got = runWanted(cmd, 1, 40*time.Second)
	for _, g := range got {
		if r, ok := g.(MultiRegistryTagsLoadedMsg); ok {
			t.Logf("tags: n=%d err=%v (%T)", len(r.Tags), r.Err, r.Err)
		}
	}
	m, _ = feedAll(t, m, got, 0)
	show(t, "unreachable tags from the form", m)
}
